import AppKit
import CoreAudio
import Observation
import SwiftUI

/// Decides which pasteboard changes are worth keeping in Clipboard history.
///
/// Skipped:
/// - items marked private by the app that wrote them (nspasteboard.org markers: concealed,
///   transient, auto-generated, plus the 1Password and macOS password markers);
/// - anything copied while an app in Settings › Clipboard › "Ignore copies from these apps" is in
///   front (password managers by default);
/// - files copied in Finder, when "File copies from Finder" is on;
/// - text written by a dictation app from that list: dictation apps work in the background, so
///   the app in front is the one you dictate into. Instead Glance checks the microphone: if a
///   listed app was recording within the last few seconds, new text is its transcript;
/// - an exact repeat of the newest item, and text shorter than 2 characters.
@MainActor
enum ClipboardFilter {
    /// Pasteboard markers that mean "do not keep this" (http://nspasteboard.org).
    static let privateTypes: [NSPasteboard.PasteboardType] = [
        .init("org.nspasteboard.ConcealedType"), .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"), .init("com.agilebits.onepassword"),
        .init("com.typeit4me.clipping"), .init("de.petermaurer.TransientPasteboardType"),
        .init("Pasteboard generator type"), .init("net.antelle.keeweb"),
    ]

    /// Never recorded, whatever the list says (system password prompts).
    static let alwaysIgnored: Set<String> = ["com.apple.SecurityAgent", "com.apple.CoreServicesUIAgent"]

    /// Password managers: the default "Ignore copies from these apps" list.
    nonisolated static let passwordManagers: [String] = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.agilebits.onepassword-osx",
        "com.agilebits.onepassword4", "com.bitwarden.desktop", "com.apple.keychainaccess", "com.apple.Passwords",
        "com.lastpass.LastPass", "com.dashlane.Dashlane", "com.dashlane.dashlanephonefinal",
        "in.sinew.Enpass-Desktop", "org.keepassxc.keepassxc", "com.keepassxc.keepassxc",
        "com.callpod.keepermac.lite", "com.nordpass.macos.NordPass",
        "com.proton.pass.electron", "me.proton.pass.electron",
    ]

    /// Terminal apps, added or removed together by the "Terminals" switch in Settings.
    nonisolated static let terminals: [String] = [
        "com.apple.Terminal", "com.mitchellh.ghostty", "com.googlecode.iterm2", "dev.warp.Warp-Stable",
        "net.kovidgoyal.kitty", "org.alacritty", "com.github.wez.wezterm",
    ]

    /// Names for list entries that are not installed on this Mac.
    nonisolated static let knownNames: [String: String] = [
        "com.1password.1password": "1Password", "com.agilebits.onepassword7": "1Password 7",
        "com.agilebits.onepassword-osx": "1Password 6", "com.agilebits.onepassword4": "1Password 4",
        "com.bitwarden.desktop": "Bitwarden", "com.apple.keychainaccess": "Keychain Access", "com.apple.Passwords": "Passwords",
        "com.lastpass.LastPass": "LastPass", "com.dashlane.Dashlane": "Dashlane", "com.dashlane.dashlanephonefinal": "Dashlane",
        "in.sinew.Enpass-Desktop": "Enpass", "org.keepassxc.keepassxc": "KeePassXC", "com.keepassxc.keepassxc": "KeePassXC",
        "com.callpod.keepermac.lite": "Keeper", "com.nordpass.macos.NordPass": "NordPass",
        "com.proton.pass.electron": "Proton Pass", "me.proton.pass.electron": "Proton Pass",
        "com.apple.Terminal": "Terminal", "com.mitchellh.ghostty": "Ghostty", "com.googlecode.iterm2": "iTerm",
        "dev.warp.Warp-Stable": "Warp", "net.kovidgoyal.kitty": "kitty", "org.alacritty": "Alacritty",
        "com.github.wez.wezterm": "WezTerm",
    ]

    /// Dictation tools are recognised by name (their bundle ids vary between versions).
    nonisolated static let dictationNames = ["wispr", "superwhisper", "macwhisper", "whisper", "aqua", "handy", "voiceink",
                                 "spokenly", "voibe", "sotto", "willow", "monologue", "typeless", "betterdictation",
                                 "voicetypr", "openwhispr", "dictat", "talktastic", "letterly", "voice type", "voicetype"]

    /// How long after a listed app stops recording its text still counts as dictation.
    static let dictationWindow: TimeInterval = 8

    // MARK: Decisions

    /// True if this pasteboard change should not be recorded at all.
    static func shouldIgnore(types: [NSPasteboard.PasteboardType], frontBundle: String?, isText: Bool, isFile: Bool = false) -> Bool {
        if types.contains(where: { privateTypes.contains($0) }) { return true }
        let list = Set(AppSettings.shared.prefs.clipboardIgnoredApps)
        if let id = frontBundle, list.contains(id) || alwaysIgnored.contains(id) { return true }
        if isFile, frontBundle == "com.apple.finder", AppSettings.shared.prefs.clipboardIgnoreFinderFiles { return true }
        if isText, MicHistory.shared.recentlyRecorded(by: list, within: dictationWindow) { return true }
        return false
    }

    /// Too short to be worth keeping (a stray character or a single space).
    static func isFragment(_ text: String) -> Bool {
        text.trimmingCharacters(in: .whitespacesAndNewlines).count < 2
    }

    // MARK: Installed dictation apps (suggestions in Settings, never added on their own)

    struct AppInfo: Identifiable, Hashable, Sendable {
        let id: String      // bundle id
        let name: String
        let path: String
    }

    /// Dictation apps found in /Applications and ~/Applications. Runs off the main thread.
    nonisolated static func installedDictationApps() async -> [AppInfo] {
        await Task.detached(priority: .utility) {
            let fm = FileManager.default
            let dirs = ["/Applications", fm.homeDirectoryForCurrentUser.appendingPathComponent("Applications").path]
            var out: [AppInfo] = []
            for d in dirs {
                for f in (try? fm.contentsOfDirectory(atPath: d)) ?? [] where f.hasSuffix(".app") {
                    let name = String(f.dropLast(4))
                    let lower = name.lowercased()
                    guard dictationNames.contains(where: { lower.contains($0) }) else { continue }
                    let path = d + "/" + f
                    guard let id = Bundle(path: path)?.bundleIdentifier, id != Bundle.main.bundleIdentifier else { continue }
                    out.append(AppInfo(id: id, name: name, path: path))
                }
            }
            return out.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        }.value
    }

    /// Display name and path for a bundle id (installed apps only).
    static func app(for id: String) -> AppInfo? {
        guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: id) else { return nil }
        return AppInfo(id: id, name: FileManager.default.displayName(atPath: url.path).replacingOccurrences(of: ".app", with: ""), path: url.path)
    }
}

/// Which apps used the microphone recently, by bundle id. Event driven (CoreAudio process
/// listeners, macOS 14.2+); nothing polls and no audio is ever read. Only bundle ids and times
/// are kept, in memory.
@MainActor
final class MicHistory {
    static let shared = MicHistory()

    private var recording: [String: Date] = [:]   // bundle id -> recording since
    private var lastSeen: [String: Date] = [:]    // bundle id -> last moment seen recording
    private var started = false
    private var listListener: AudioObjectPropertyListenerBlock?
    private var processListeners: [AudioObjectID: AudioObjectPropertyListenerBlock] = [:]

    /// Simulation for tests (debug channel): bundle id treated as "just finished recording".
    var simulated: (id: String, at: Date)?

    func start() {
        guard !started else { return }
        started = true
        var sys = Self.address(kAudioHardwarePropertyProcessObjectList)
        let b: AudioObjectPropertyListenerBlock = { _, _ in MainActor.assumeIsolated { MicHistory.shared.refresh() } }
        if AudioObjectAddPropertyListenerBlock(AudioObjectID(kAudioObjectSystemObject), &sys, .main, b) == noErr { listListener = b }
        refresh()
    }

    func stop() {
        guard started else { return }
        started = false
        var sys = Self.address(kAudioHardwarePropertyProcessObjectList)
        if let b = listListener { AudioObjectRemovePropertyListenerBlock(AudioObjectID(kAudioObjectSystemObject), &sys, .main, b) }
        listListener = nil
        var run = Self.address(kAudioProcessPropertyIsRunningInput)
        for (id, b) in processListeners { AudioObjectRemovePropertyListenerBlock(id, &run, .main, b) }
        processListeners.removeAll()
        recording.removeAll()
    }

    /// Re-read who is recording; remember when each app stopped.
    func refresh() {
        let processes = CameraGuard.audioProcesses()
        var run = Self.address(kAudioProcessPropertyIsRunningInput)
        for id in processListeners.keys where !processes.contains(id) {
            if let b = processListeners[id] { AudioObjectRemovePropertyListenerBlock(id, &run, .main, b) }
            processListeners[id] = nil
        }
        for id in processes where processListeners[id] == nil {
            let b: AudioObjectPropertyListenerBlock = { _, _ in MainActor.assumeIsolated { MicHistory.shared.refresh() } }
            if AudioObjectAddPropertyListenerBlock(id, &run, .main, b) == noErr { processListeners[id] = b }
        }
        let now = Date()
        let current = Set(CameraGuard.micClients().compactMap(\.bundle))
        for id in current where recording[id] == nil { recording[id] = now }
        for id in current { lastSeen[id] = now }
        for id in Array(recording.keys) where !current.contains(id) {
            recording[id] = nil
            lastSeen[id] = now   // it stopped just now
        }
    }

    /// True if one of `ids` is recording now (for at most 2 minutes, so an always-on microphone or a
    /// call does not hide every copy) or stopped recording within `window` seconds.
    func recentlyRecorded(by ids: Set<String>, within window: TimeInterval) -> Bool {
        guard !ids.isEmpty else { return false }
        if let s = simulated, Date().timeIntervalSince(s.at) < window, ids.contains(s.id) { return true }
        guard started else { return false }
        refresh()
        let now = Date()
        func matches(_ bundle: String) -> Bool { ids.contains(bundle) || ids.contains { bundle.hasPrefix($0 + ".") } }
        for (b, since) in recording where matches(b) && now.timeIntervalSince(since) < 120 { return true }
        for (b, seen) in lastSeen where matches(b) && recording[b] == nil && now.timeIntervalSince(seen) < window { return true }
        return false
    }

    private static func address(_ selector: AudioObjectPropertySelector) -> AudioObjectPropertyAddress {
        AudioObjectPropertyAddress(mSelector: selector, mScope: kAudioObjectPropertyScopeGlobal, mElement: kAudioObjectPropertyElementMain)
    }
}

// MARK: - Settings › Clipboard › Ignore copies from these apps

struct ClipboardIgnoreSettings: View {
    @Bindable private var settings = AppSettings.shared
    @State private var dictationApps: [ClipboardFilter.AppInfo] = []

    private var list: [String] { settings.prefs.clipboardIgnoredApps }

    var body: some View {
        let installed = list.compactMap(ClipboardFilter.app(for:))
        let notInstalled = list.filter { ClipboardFilter.app(for: $0) == nil }
        let suggestions = dictationApps.filter { !list.contains($0.id) && !settings.prefs.clipboardDismissedSuggestions.contains($0.id) }
        VStack(alignment: .leading, spacing: 6) {
            Toggle("Ignore copies from terminals (Terminal, Ghostty, iTerm, Warp and others)", isOn: terminalsIgnored)
            Toggle("Ignore file copies from Finder", isOn: $settings.prefs.clipboardIgnoreFinderFiles)
            Text("Ignore copies from these apps")
            ForEach(installed) { app in
                HStack {
                    Image(nsImage: NSWorkspace.shared.icon(forFile: app.path)).resizable().frame(width: 18, height: 18)
                    Text(app.name)
                    if dictationApps.contains(where: { $0.id == app.id }) {
                        Text("dictation").font(.caption2).foregroundStyle(.secondary)
                    }
                    Spacer()
                    Button(role: .destructive) { settings.prefs.clipboardIgnoredApps.removeAll { $0 == app.id } } label: {
                        Image(systemName: "minus.circle")
                    }
                    .buttonStyle(.borderless)
                    .help("Stop ignoring \(app.name)")
                }
            }
            if !notInstalled.isEmpty {
                let names = Array(Set(notInstalled.map { ClipboardFilter.knownNames[$0] ?? $0 })).sorted()
                Text("Also ignored if you install them: \(names.joined(separator: ", ")).")
                    .font(.caption).foregroundStyle(.secondary)
            }
            ForEach(suggestions) { app in
                HStack {
                    Image(nsImage: NSWorkspace.shared.icon(forFile: app.path)).resizable().frame(width: 18, height: 18)
                    VStack(alignment: .leading, spacing: 1) {
                        Text("\(app.name) is a dictation app")
                        Text("Ignore the text it pastes for you?").font(.caption).foregroundStyle(.secondary)
                    }
                    Spacer()
                    Button("Ignore") { settings.prefs.clipboardIgnoredApps.append(app.id) }
                    Button("Not Now") { settings.prefs.clipboardDismissedSuggestions.append(app.id) }
                }
            }
            HStack {
                Button("Add App…", action: addApp)
                Spacer()
            }
            Text("Copies made while one of these apps is in front are not kept. Dictation apps type into other apps, so for them Glance also skips new text that appears within a few seconds after the app used the microphone. Only app names and times are checked; no audio is read.")
                .font(.caption).foregroundStyle(.secondary)
        }
        .task { dictationApps = await ClipboardFilter.installedDictationApps() }
    }

    /// On when any terminal is in the list; switching it adds or removes all of them together.
    private var terminalsIgnored: Binding<Bool> {
        Binding(get: { ClipboardFilter.terminals.contains(where: list.contains) }, set: { on in
            var l = settings.prefs.clipboardIgnoredApps.filter { !ClipboardFilter.terminals.contains($0) }
            if on { l += ClipboardFilter.terminals }
            settings.prefs.clipboardIgnoredApps = l
        })
    }

    private func addApp() {
        let p = NSOpenPanel()
        p.allowedContentTypes = [.application]
        p.directoryURL = URL(fileURLWithPath: "/Applications")
        p.allowsMultipleSelection = true
        guard p.runModal() == .OK else { return }
        for u in p.urls {
            if let id = Bundle(url: u)?.bundleIdentifier, !settings.prefs.clipboardIgnoredApps.contains(id) {
                settings.prefs.clipboardIgnoredApps.append(id)
            }
        }
    }
}
